mapper.select:
SELECT FROM iam_application_service WHERE deleted = FALSE
AND id IN #{item}
AND 1 = 0

SELECT 
FROM iam_application_service

    realm_id = #{realmId} AND deleted = FALSE
    AND app_code LIKE '%' || #{app.appCode} || '%'
    AND app_name LIKE '%' || #{app.appName} || '%'
    AND app_type = #{app.appType}
    AND category = #{app.category}
    AND visibility = #{app.visibility}
    AND authorization_mode = #{app.authorizationMode}
    AND enabled = #{app.enabled}

ORDER BY sort_order, id
